import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        FastInput fi = new FastInput();
        PrintWriter pw = new PrintWriter(System.out);

        long n = fi.nextLong();
        long m = fi.nextLong();
        long k = n * m;
        long l = fi.nextLong();
        long r = fi.nextLong();
        long len = r - l + 1;
        long MOD = 998244353;

        long ans;
        if (k % 2 == 1) {
            ans = modPow(len, k, MOD);
        } else {
            long t1 = modPow(len, k, MOD);
            long t2 = modPow(len % 2, k, MOD);
            ans = (t1 + t2) % MOD;
            ans = ans * modPow(2, MOD - 2, MOD) % MOD;
        }

        pw.println(ans);
        pw.close();
    }

    private static long modPow(long b, long e, long m) {
        b %= m;
        long res = 1;
        while (e > 0) {
            if ((e & 1) == 1) res = (res * b) % m;
            b = (b * b) % m;
            e >>= 1;
        }
        return res;
    }

    static class FastInput {
        private final InputStream is = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = is.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        private long nextLong() {
            try {
                int c = read();
                while (c <= 32) c = read();
                int sign = 1;
                if (c == '-') {
                    sign = -1;
                    c = read();
                }
                long val = 0;
                while (c > 32) {
                    val = val * 10 + c - '0';
                    c = read();
                }
                return val * sign;
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }
    }
}
